import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import SmartTourism from './pages/SmartTourism';
import TribalHeritage from './pages/TribalHeritage';
import TribalProducts from './pages/TribalProducts';
import BadagaLink from './pages/BadagaLink';
import './App.css';

function ProtectedRoute({ children }) {
  const { user } = useAuth();
  return user ? children : <Navigate to="/login" />;
}

function App() {
  return (
    <AuthProvider>
      <Router>
        <Routes>
          <Route path="/login" element={<Login />} />
          <Route
            path="/"
            element={
              <ProtectedRoute>
                <Dashboard />
              </ProtectedRoute>
            }
          />
          <Route
            path="/smart-tourism"
            element={
              <ProtectedRoute>
                <SmartTourism />
              </ProtectedRoute>
            }
          />
          <Route
            path="/tribal-heritage"
            element={
              <ProtectedRoute>
                <TribalHeritage />
              </ProtectedRoute>
            }
          />
          <Route
            path="/tribal-products"
            element={
              <ProtectedRoute>
                <TribalProducts />
              </ProtectedRoute>
            }
          />
          <Route
            path="/badaga-link"
            element={
              <ProtectedRoute>
                <BadagaLink />
              </ProtectedRoute>
            }
          />
        </Routes>
      </Router>
    </AuthProvider>
  );
}

export default App;
